import { MeshStandardNodeMaterial } from 'three/webgpu';
import { position, mix, clamp, vec3, time, sin, cos, mul, add, sub, divide, length, normalize } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as primitiveParticleEmerge } from '@/primitives';
import { createText as createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, InstancedMesh, IcosahedronGeometry, Color, AdditiveBlending, NormalBlending, TextureLoader } = ctx.THREE;

  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeo = new ctx.THREE.PlaneGeometry(7, 6);
  const gradientMat = new MeshStandardNodeMaterial();
  const uvNode = ctx.threeNode ? ctx.threeNode.uv : undefined; // placeholder, will be replaced by node import
  // Build vertical gradient using node material
  const gradStop0 = new Color('#0b0b10');
  const gradStop1 = new Color('#16161d');
  const vUv = ctx.threeNode ? ctx.threeNode.uv : undefined;
  const gradColor = mix(
    gradStop0,
    gradStop1,
    vUv.y
  );
  gradientMat.colorNode = gradColor;
  gradientMat.roughness = 1;
  gradientMat.metalness = 0;
  gradientMat.side = ctx.THREE.DoubleSide;
  const backdrop = new ctx.THREE.Mesh(backdropGeo, gradientMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- PARTICLE FIELD ----------
  const particleCount = 1200;
  const particleGeo = new IcosahedronGeometry(0.012, 0);
  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.color = new Color('#e8ecf2');
  fieldMat.metalness = 0;
  fieldMat.roughness = 1;
  fieldMat.transparent = true;
  fieldMat.depthWrite = false;
  // Opacity based on depth (z)
  const posZ = position.z;
  const t = clamp(divide(negate(posZ), 5), 0, 1);
  const opacityNode = mix(0.9, 0.15, t);
  fieldMat.opacityNode = opacityNode;
  fieldMat.blending = NormalBlending;

  const fieldInst = new InstancedMesh(particleGeo, fieldMat, particleCount);
  // Distribute instances in ellipsoidal shell 6x4x5 centered at (0,0,-1.5)
  const dummy = new ctx.THREE.Object3D();
  for (let i = 0; i < particleCount; i++) {
    const phi = Math.acos(2 * Math.random() - 1);
    const theta = 2 * Math.PI * Math.random();
    const radius = 0.5 + Math.random() * 2.5; // shell thickness
    const x = Math.sin(phi) * Math.cos(theta) * 3; // semi-axis 3 (6/2)
    const y = Math.sin(phi) * Math.sin(theta) * 2; // semi-axis 2 (4/2)
    const z = Math.cos(phi) * 2.5 - 1.5; // semi-axis 2.5 (5/2) offset -1.5
    dummy.position.set(x, y, z);
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    fieldInst.setMatrixAt(i, dummy.matrix);
  }
  root.add(fieldInst);

  // ---------- CORE PARTICLES ----------
  const coreCount = 90;
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color('#ff2a38');
  coreMat.emissive = new Color('#ff2a38');
  coreMat.emissiveIntensity = 1.8;
  coreMat.metalness = 0;
  coreMat.roughness = 1;
  coreMat.transparent = true;
  coreMat.blending = AdditiveBlending;
  coreMat.depthWrite = false;

  const coreInst = new InstancedMesh(particleGeo, coreMat, coreCount);
  for (let i = 0; i < coreCount; i++) {
    const phi = Math.acos(2 * Math.random() - 1);
    const theta = 2 * Math.PI * Math.random();
    const r = Math.random() * 0.5;
    const x = Math.sin(phi) * Math.cos(theta) * r;
    const y = Math.sin(phi) * Math.sin(theta) * r;
    const z = Math.cos(phi) * r;
    dummy.position.set(x, y, z);
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    coreInst.setMatrixAt(i, dummy.matrix);
  }
  root.add(coreInst);

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 48,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
      maxWidthPx: 1024,
      letterSpacingPx: (item.typography?.letterSpacing ?? 0) * (item.typography?.fontSize ?? 48)
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position according to role
    if (item.role === 'hero') {
      txt.position.set(0, 0.5, 0.5);
    } else if (item.role === 'subhead') {
      txt.position.set(0, -0.25, 0.5);
    } else {
      // caption or default
      txt.position.set(0, -2.25, 0.5);
    }
    root.add(txt);
  }

  // ---------- CINEMATIC PRIMITIVE ----------
  const primitive = ctx.primitives['particle-emerge'](root, {
    count: particleCount,
    durationMs: 1400
  });

  // ---------- CORE PULSE ANIMATION ----------
  const pulseTL = gsap.timeline({ repeat: -1, yoyo: true, ease: 'sine.inOut' });
  pulseTL.to(coreMat, { emissiveIntensity: 1.5, duration: 5 })
         .to(coreMat, { emissiveIntensity: 1.8, duration: 5 });

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    fieldMat.dispose();
    coreMat.dispose();
    particleGeo.dispose();
    backdropGeo.dispose();
    primitive.cleanup();
    pulseTL.kill();
  };

  // No interaction handlers required
  root.userData.handlers = {};

  return root;
}
